<?php
namespace App\Services; use App\Models\{Attendance,SchoolSetting,Student,User}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class AttendanceService{public function scan(string $token,User $user):Attendance{$student=Student::with('schoolClass')->where('barcode_token',$token)->first();if(!$student||!$student->is_active)throw ValidationException::withMessages(['token'=>'Barcode tidak ditemukan atau sudah tidak aktif.']);if($user->isWali()&&(int)$user->class_id!==(int)$student->class_id)throw ValidationException::withMessages(['token'=>'Siswa bukan anggota kelas Anda.']);$date=now('Asia/Jakarta')->toDateString();if(Attendance::whereBelongsTo($student)->whereDate('attendance_date',$date)->exists())throw ValidationException::withMessages(['token'=>'Siswa sudah melakukan absensi hari ini.']);$limit=SchoolSetting::value('late_time_limit')?:'07:15:00';$time=now('Asia/Jakarta');return DB::transaction(fn()=>Attendance::create(['student_id'=>$student->id,'attendance_date'=>$date,'check_in_time'=>$time->format('H:i:s'),'status'=>$time->format('H:i:s')>$limit?'terlambat':'hadir','method'=>'barcode','recorded_by'=>$user->id,'scanned_token'=>$token]));}}
